    /** Декоративные детали (скрываются в облегчённом режиме). */
    public static List<ModelPart> decor(ModelPart root) {
        List<ModelPart> list = new ArrayList<>();
        list.add(root.getChild("head").getChild("crown").getChild("crown_spine_0"));
        list.add(root.getChild("head").getChild("crown").getChild("crown_spine_1"));
        list.add(root.getChild("head").getChild("crown").getChild("crown_spine_2"));
        list.add(root.getChild("head").getChild("crown").getChild("crown_spine_3"));
        list.add(root.getChild("head").getChild("crown").getChild("crown_spine_4"));
        list.add(root.getChild("abdomen").getChild("rear_spine_0"));
        list.add(root.getChild("abdomen").getChild("rear_spine_1"));
        list.add(root.getChild("abdomen").getChild("rear_spine_2"));
        list.add(root.getChild("abdomen").getChild("rear_spine_3"));
        return list;
    }
